from markdownify import markdownify

nested_html = (
    '<ul><li>1<ul><li>a<ul><li>I</li><li>II</li><li>III</li></ul></li>'
    '<li>b</li><li>c</li></ul></li><li>2</li><li>3</li></ul>'
)
lines = markdownify(nested_html).strip().splitlines()
levels = {"star": 0, "plus": 0, "dash": 0}
for line in lines:
    stripped = line.strip()
    if stripped.startswith("*"):
        levels["star"] += 1
    elif stripped.startswith("+"):
        levels["plus"] += 1
    elif stripped.startswith("-"):
        levels["dash"] += 1

print(lines)
print(levels)
print(lines[2:5])
